(function(){'use strict';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clone=v=>JSON.parse(JSON.stringify(v)),uid=()=>crypto.randomUUID(),today=()=>new Date().toLocaleDateString('en-CA',{timeZone:'Europe/Prague'}),stamp=v=>v?new Date(v).toLocaleString('cs-CZ',{timeZone:'Europe/Prague'}):'Dosud neuloženo';
const slugify=v=>String(v).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,80);
let me=null,state=null,school=null,page='dashboard',dirty=false,busy=false,activePost=null,activeTeacher=null,activePage=null,activeSection=null,activeEvent=null,activeExam=null,activeRoom=null,activeDocument=null,activeUser=null,reportFilter='new',reportOffset=0,uploadTarget=null,media=[],cropImage=null,cropName='',cropObjectURL='';
const owner=()=>me?.role==='admin'&&me?.username==='kubicek';
const sectionNames={home:'Hlavní stránka',news:'Aktuality',schedule:'Naše třída',teachers:'Učitelé',plans:'Půdorysy',events:'Školní kalendář',sources:'Zdroje a podklady'};
const nav=[['dashboard','Přehled','M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z'],['news','Aktuality','M4 4h16v16H4z M8 8h8 M8 12h8 M8 16h5'],['teachers','Učitelé a rozvrhy','M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M18 8h4 M20 6v4'],['pages','Stránky a sekce','M6 3h9l4 4v14H6z M14 3v5h5 M9 12h7 M9 16h7'],['calendar','Kalendář','M4 5h16v16H4z M4 10h16 M8 2v6 M16 2v6'],['documents','Dokumenty','M5 3h10l4 4v14H5z M14 3v5h5 M9 12h6 M9 16h6'],['media','Mediatéka','M3 4h18v16H3z M3 16l5-5 4 4 3-3 6 6 M15 8h.01'],['settings','Vzhled a nastavení','M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M19 5l-2 2 M7 17l-2 2'],['users','Redakce a účty','M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M18 8h4 M20 6v4'],['reports','Podněty a chyby','M4 3h16v14H9l-5 4z M8 7h8 M8 11h5'],['history','Historie a záloha','M3 12a9 9 0 1 0 3-7 M3 3v6h6 M12 7v5l3 2'],['account','Můj účet','M7 10V7a5 5 0 0 1 10 0v3 M5 10h14v11H5z M12 14v3']];
function icon(path){return `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${path}"/></svg>`}
function message(text='',type=''){const el=me?$('#admin-message'):$('#login-message');el.textContent=text;el.className=type;if(text)el.scrollIntoView({block:'nearest',behavior:'smooth'})}
function mark(){dirty=true;const el=$('#dirty-state');if(el)el.textContent='Neuložené změny.'}
function title(name,desc,actions=''){return `<div class="page-title"><div><div class="eyebrow">SPRÁVA ŠKOLNÍHO WEBU</div><h1>${name}</h1><p>${desc}</p></div>${actions?`<div class="title-actions">${actions}</div>`:''}</div>`}
function field(name,label,value='',options={}){return `<label${options.full?' class="full"':''}>${label}${options.area?`<textarea name="${name}" rows="${options.rows||4}" maxlength="${options.max||3000}" ${options.required?'required':''}>${esc(value)}</textarea>`:`<input name="${name}" type="${options.type||'text'}" value="${esc(value)}" maxlength="${options.max||200}" ${options.required?'required':''} ${options.min?`minlength="${options.min}"`:''} ${options.id?`id="${options.id}"`:''} ${options.readonly?'readonly':''}>`}${options.help?`<small>${options.help}</small>`:''}</label>`}
function uploadField(name,label,value='',accept='image/*',help=''){return `<div class="upload-widget"><label for="field-${name}">${label}</label><span class="upload-field"><input name="${name}" id="field-${name}" value="${esc(value)}" placeholder="Nahraj soubor nebo vlož HTTPS adresu"><button type="button" class="secondary" data-upload="field-${name}" data-accept="${accept}">Nahrát soubor</button><button type="button" class="secondary" data-choose-media="field-${name}" data-accept="${accept}">Z mediatéky</button></span>${help?`<small>${help}</small>`:''}</div>`}
function actions(label='Uložit a zveřejnit',extra=''){return `<div class="form-actions"><span class="muted" id="dirty-state">${stamp(state?.updatedAt)}</span>${extra}<button type="submit" class="primary">${label}</button></div>`}
const reportStatuses={new:'Nové',working:'Řeší se',resolved:'Vyřešené'},reportCategories={schedule:'Rozvrh',teacher:'Vyučující a kontakty',lunch:'Jídelníček',technical:'Technická chyba',other:'Jiný podnět'};
async function reportsList(){const r=await api({action:'reports_list',status:reportFilter,offset:reportOffset});return title('Podněty a chyby.','Soukromá schránka hlášení od návštěvníků. Přístup má pouze hlavní administrátor.',`<button class="secondary" data-go="reports">Obnovit přehled</button>`)+`<div class="report-filters">${Object.entries({...reportStatuses,all:'Všechny'}).map(([id,label])=>`<button class="secondary" data-report-filter="${id}" aria-pressed="${id===reportFilter}">${label} · ${id==='all'?Object.values(r.counts).reduce((a,b)=>a+b,0):r.counts[id]||0}</button>`).join('')}</div><p class="muted">${r.total} podnětů v tomto výběru · texty se nezveřejňují na webu.</p><div class="report-inbox">${r.reports.map(item=>`<article class="panel report-item"><div class="panel-head"><h2>${esc(reportCategories[item.category]||'Podnět')}</h2><span class="badge">${esc(reportStatuses[item.status])}</span></div><p class="muted">${stamp(item.created_at)} · <a class="text-button" href="index.html${esc(item.page)}" target="_blank" rel="noopener">${esc(item.page)} ↗</a></p><p class="report-message">${esc(item.message)}</p><form class="report-manage-form form-stack" data-id="${esc(item.id)}" data-revision="${item.revision}"><label>Stav<select name="status">${Object.entries(reportStatuses).map(([id,label])=>`<option value="${id}" ${id===item.status?'selected':''}>${label}</option>`).join('')}</select></label><label>Interní poznámka<textarea name="note" maxlength="2000" rows="2" placeholder="Co je potřeba ověřit nebo jak byla chyba opravena…">${esc(item.note)}</textarea></label><div class="form-actions"><small class="muted">Aktualizováno: ${stamp(item.updated_at)}</small><button class="primary" type="submit">Uložit stav a poznámku</button></div></form></article>`).join('')||'<section class="panel empty"><strong>Žádné podněty v tomto výběru.</strong>Nová hlášení se objeví tady.</section>'}</div><div class="report-pagination">${r.offset>0?`<button class="secondary" data-report-offset="${Math.max(0,r.offset-50)}">← Předchozí</button>`:''}${r.offset+50<r.total?`<button class="secondary" data-report-offset="${r.offset+50}">Další →</button>`:''}</div>`}
function photo(t,large=false){const fallback='assets/portraits/alien-'+((t.fallbackAvatar||(t.role==='učitelka'?'female':'male'))==='female'?'girl':'boy')+'.webp';return `<img id="${large?'teacher-photo-preview':''}" class="teacher-photo ${large?'large':''}" src="${esc(t.photo||fallback)}" alt="${esc(t.name)}">`}

function allTeachers(){return state.content.teachers??school.teachers}
function allExams(){return state.content.exams||[]}
function allEvents(){return state.content.events??school.events.map((e,i)=>({...e,id:'event-'+i}))}
function formObject(form){return Object.fromEntries(new FormData(form).entries())}
function showLogin(text=''){me=null;$('#admin-screen').hidden=true;$('#auth-screen').hidden=false;$('#login-form').reset();message(text)}
async function api(body){const response=await fetch(new URL('api/admin',document.baseURI),{method:body?'POST':'GET',credentials:'same-origin',cache:'no-store',headers:body?{'Content-Type':'application/json','X-Portal-Action':'1'}:{},...(body?{body:JSON.stringify(body)}:{}),signal:AbortSignal.timeout(20000)});let result;try{result=await response.json()}catch{throw Error('Správa potřebuje hostovanou serverovou verzi. Otevři odkaz Správa na veřejném webu.')}if(!response.ok){if(response.status===401&&body?.action!=='login')showLogin('Přihlášení vypršelo. Přihlas se znovu.');throw Error(result.error||'Požadavek se nezdařil.')}return result}
async function run(fn){if(busy)return;busy=true;$$('button[type="submit"], [data-save-news]').forEach(b=>b.disabled=true);try{await fn()}catch(e){message(e.name==='TimeoutError'?'Server neodpověděl včas. Úpravy zůstaly rozepsané; zkus uložení znovu.':e.message||'Spojení se nezdařilo.','error')}finally{busy=false;$$('button[type="submit"], [data-save-news]').forEach(b=>b.disabled=false)}}
async function saveContent(patch,after=page){const result=await api({action:'save',revision:state.revision,content:{...state.content,...patch}});state={...state,...result};dirty=false;await show(after,true);message('Uloženo a zveřejněno. Změny se ostatním návštěvníkům obnoví nejpozději do minuty.','success')}
async function initSession(result){me={username:result.username,role:result.role,displayName:result.displayName};state={content:result.content,revision:result.revision,updatedAt:result.updatedAt};if(!school){const r=await fetch(new URL('assets/data.json',document.baseURI));if(!r.ok)throw Error('Nelze načíst školní podklady. Obnov stránku.');school=await r.json()}$('#auth-screen').hidden=true;$('#admin-screen').hidden=false;$('#account-name').textContent=me.displayName||me.username;$('#account-role').textContent=owner()?'Hlavní administrátor':'Redaktor';renderNav();dirty=false;await show('dashboard',true)}
function renderNav(){$('#admin-nav').innerHTML=nav.filter(n=>owner()||['dashboard','news','calendar','media','account'].includes(n[0])).map(([id,label,path],i)=>`${i===0?'<span class="nav-group">PRACOVNÍ PROSTOR</span>':''}${id==='settings'?'<span class="nav-group">SPRÁVA WEBU</span>':''}<button data-go="${id}" ${page===id?'aria-current="page"':''}>${icon(path)}<span>${id==='calendar'&&!owner()?'Písemky 1.A':label}</span></button>`).join('')}
async function show(target,force=false){if(dirty&&!force&&!confirm('Máš neuložené změny. Opravdu přejít jinam a zahodit je?'))return;if(target==='rooms')target='dashboard';if(!owner()&&!['dashboard','news','calendar','media','account'].includes(target))target='dashboard';dirty=false;page=target;document.body.classList.remove('menu-open');message();renderNav();$('#workspace-crumb').textContent=nav.find(n=>n[0]===page)?.[1]||'Přehled';const views={dashboard,news:newsList,teachers:teacherList,pages:pagesList,calendar:calendarList,rooms:roomsList,documents:documentsList,settings:settingsView,account:accountView,media:mediaView,users:usersView,reports:reportsList,history:historyView};$('#workspace').innerHTML=await views[page]();window.scrollTo(0,0)}
function dashboard(){const posts=state.content.posts||[];const stats=[['AKTUALITY',posts.filter(p=>p.status==='published').length,'Zveřejněno'],['KONCEPTY',posts.filter(p=>p.status==='draft').length,'Rozepsané články'],...(owner()?[['VYUČUJÍCÍ',allTeachers().length,'Profily a rozvrhy'],['VLASTNÍ STRÁNKY',state.content.pages.length,'Obsah pro návštěvníky']]:[])];return title(`Vítej, ${esc(me.displayName||me.username)}.`,owner()?'Celý školní web pod tvojí kontrolou.':'Tvoje aktuality, koncepty a redakční práce.',`<button class="primary" data-new-post>+ Napsat aktualitu</button>`)+`<div class="stats">${stats.map(([label,note,desc])=>`<div class="stat"><small>${label}</small><b>${note}</b><span>${desc}</span></div>`).join('')}</div><div class="two-col"><section class="panel"><div class="panel-head"><h2>Poslední aktuality</h2><button class="text-button" data-go="news">Všechny →</button></div>${posts.length?`<div class="simple-list">${posts.slice(0,5).map(p=>`<div class="simple-row"><div><strong>${esc(p.title)}</strong><p class="muted">${esc(p.category)} · ${p.status==='draft'?'Koncept':'Zveřejněno'}</p></div><button class="text-button" data-edit-post="${esc(p.id)}">Upravit →</button></div>`).join('')}</div>`:'<div class="empty"><strong>Začni prvním článkem.</strong>Aktuality se po zveřejnění zobrazí na hlavní stránce i v sekci Aktuality.</div>'}</section><section class="panel"><h2>${owner()?'Rychlé úpravy':'Tvoje redakční oprávnění'}</h2>${owner()?`<div class="simple-list">${[['teachers','Vyučující a jejich fotografie'],['pages','Texty jednotlivých sekcí'],['users','Přidat člena redakce'],['reports','Nahlášené chyby a podněty'],['settings','Vzhled a hlavní stránka']].map(([id,label])=>`<button class="secondary" data-go="${id}">${label} →</button>`).join('')}</div>`:'<p class="muted">Můžeš psát vlastní aktuality, ukládat koncepty, nahrávat fotografie a zapisovat písemky 1.A v Kalendáři. Správu ostatních sekcí a účtů má hlavní administrátor.</p>'}<p class="muted">Poslední změna obsahu: ${stamp(state.updatedAt)}<br>Přihlášený účet: ${esc(me.username)}</p></section></div>`}
function newsList(){activePost=null;return title('Aktuality.',owner()?'Školní redakce, nové články i rozepsané koncepty.':'Tvoje články. Koncepty nejsou veřejně viditelné.',`<button class="primary" data-new-post>+ Nová aktualita</button>`)+`<section class="panel"><div class="toolbar"><input id="news-search" type="search" placeholder="Hledat článek…" aria-label="Hledat aktualitu"><select id="news-filter" aria-label="Stav aktuality"><option value="all">Všechny stavy</option><option value="published">Zveřejněné</option><option value="draft">Koncepty</option></select></div><div id="news-table">${newsTable()}</div></section>`}
function newsTable(){const q=($('#news-search')?.value||'').toLocaleLowerCase('cs'),filter=$('#news-filter')?.value||'all';const posts=state.content.posts.filter(p=>p.title.toLocaleLowerCase('cs').includes(q)&&(filter==='all'||p.status===filter));return posts.length?`<div class="table-wrap"><table><thead><tr><th>Aktualita</th><th>Autor</th><th>Stav</th><th>Datum</th><th></th></tr></thead><tbody>${posts.map(p=>`<tr><td><strong>${esc(p.title)}</strong><div class="muted">${esc(p.category)}</div></td><td>${esc(p.author)}</td><td><span class="badge ${p.status==='published'?'green':''}">${p.status==='published'?'Zveřejněno':'Koncept'}</span></td><td>${esc(p.date||'—')}</td><td><div class="row-actions"><button class="text-button" data-edit-post="${esc(p.id)}">Upravit</button><button class="text-button" data-delete-post="${esc(p.id)}">Odebrat</button></div></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty"><strong>Žádné aktuality.</strong>Vytvoř nový článek nebo změň hledání.</div>'}
function editPost(id){if(!discard())return;activePost=clone(state.content.posts.find(p=>p.id===id)||{id:uid(),title:'',body:'',excerpt:'',category:'Ze školy',date:today(),cover:'',status:'draft'});$('#workspace').innerHTML=title(id?'Upravit aktualitu.':'Nová aktualita.','Text můžeš nejprve uložit jako koncept nebo rovnou zveřejnit.',`<button class="secondary" data-go="news">← Seznam článků</button>`)+`<form id="post-form"><div class="two-col"><section class="panel form-stack">${field('title','Nadpis',activePost.title,{required:true,max:160})}${field('excerpt','Perex · krátké uvedení článku',activePost.excerpt,{area:true,rows:3,max:300})}${field('body','Text aktuality',activePost.body,{area:true,rows:16,max:20000})}<div class="editor-help"><span>Nový odstavec: prázdný řádek.</span><span>Text se zobrazuje bezpečně bez HTML.</span></div></section><section class="panel form-stack"><h2>Publikování</h2>${field('category','Rubrika',activePost.category,{max:50})}${field('date','Datum',activePost.date,{type:'date'})}${uploadField('cover','Úvodní fotografie',activePost.cover,'image/jpeg,image/png,image/webp')}${activePost.cover?`<img id="post-image-preview" class="image-preview" src="${esc(activePost.cover)}" alt="Náhled fotografie">`:'<div id="post-image-preview"></div>'}<p class="muted">Aktuální stav: <b>${activePost.status==='draft'?'koncept':'zveřejněno'}</b><br>Autor: ${esc(activePost.author||me.username)}</p></section></div><div class="panel form-actions"><span class="muted" id="dirty-state">Koncept vidí jen redakce s oprávněním.</span><button class="secondary" type="button" data-preview-post>Náhled</button><button class="secondary" type="button" data-save-news="draft">Uložit koncept</button><button class="primary" type="submit">Zveřejnit aktualitu</button></div></form>`}
function collectPost(){return{...activePost,...formObject($('#post-form'))}}
async function savePost(status){const form=$('#post-form');if(!form.reportValidity())return;const result=await api({action:'news_save',revision:state.revision,post:{...collectPost(),status}});state={...state,...result};dirty=false;await show('news',true);message(status==='draft'?'Koncept je uložený. Na veřejném webu není vidět.':'Aktualita je zveřejněná.','success')}
function teacherList(){activeTeacher=null;return title('Učitelé a rozvrhy.','Fotografie, kontakty, předměty a poznámky na jednom místě.',`<button class="primary" data-new-teacher>+ Přidat učitele</button>`)+`<section class="panel"><div class="toolbar"><input id="teacher-admin-search" type="search" placeholder="Jméno, kabinet, předmět…" aria-label="Hledat učitele"></div><div id="teacher-admin-table">${teachersTable()}</div></section>`}
function teachersTable(){const q=($('#teacher-admin-search')?.value||'').toLocaleLowerCase('cs');const ts=allTeachers().filter(t=>(t.name+' '+t.room+' '+t.subjects.join(' ')).toLocaleLowerCase('cs').includes(q));return `<div class="table-wrap"><table><thead><tr><th>Vyučující</th><th>Kabinet</th><th>Rozvrh</th><th></th></tr></thead><tbody>${ts.map(t=>`<tr><td><div class="teacher-cell">${photo(t)}<div><strong>${esc(t.name)}</strong><div class="muted">${esc(t.title)} · ${esc(t.subjects.join(', '))}</div></div></div></td><td>${esc(t.room||'—')}</td><td><span class="badge ${t.schedule.length?'blue':''}">${t.schedule.length} hodin</span></td><td><div class="row-actions"><button class="text-button" data-edit-teacher="${esc(t.id)}">Upravit</button><button class="text-button" data-delete-teacher="${esc(t.id)}">Odebrat</button></div></td></tr>`).join('')}</tbody></table></div>`}
function editTeacher(id){if(!discard())return;activeTeacher=clone(allTeachers().find(t=>t.id===id)||{id:'ucitel-'+uid(),name:'Nový učitel',first:'',last:'',title:'',suffix:'',code:'',role:'vyučující',room:'',phone:'',email:'',classroom:'',photo:'',subjects:[],schedule:[],duties:'',pdf:'',scheduleSource:''});const t=activeTeacher;$('#workspace').innerHTML=title(id?'Profil vyučujícího.':'Nový vyučující.','Změny profilu a rozvrhu se uloží společně.',`<button class="secondary" data-go="teachers">← Seznam učitelů</button>`)+`<form id="teacher-form"><section class="panel"><div class="photo-editor">${photo(t,true)}<div><h2>Portrétní fotografie</h2><p class="muted">Vyber obličej, nastav výřez a přiblížení. Výsledkem bude kruhový portrét.</p><button class="secondary" type="button" data-crop-teacher>Nahrát a oříznout fotografii</button> <button class="text-button" type="button" data-remove-photo>Odstranit fotografii</button><input type="hidden" name="photo" id="field-photo" value="${esc(t.photo)}"></div></div></section><section class="panel"><h2>Základní údaje</h2><div class="form-grid">${field('first','Jméno',t.first,{required:true,max:80})}${field('last','Příjmení',t.last,{required:true,max:100})}${field('title','Titul před jménem',t.title,{max:80})}${field('suffix','Titul za jménem',t.suffix,{max:80})}${field('code','Zkratka v rozvrhu',t.code,{max:15})}${field('role','Pozice',t.role,{max:100})}${field('room','Kabinet',t.room,{max:100})}${field('classroom','Třídnictví · třída',t.classroom,{max:30})}${field('email','E-mail',t.email,{type:'email',max:160})}${field('phone','Telefon',t.phone,{max:40})}${field('subjects','Předměty · odděl čárkou',t.subjects.join(', '),{full:true,max:2000})}</div></section><section class="panel"><div class="panel-head"><h2>Týdenní rozvrh</h2><button class="secondary" type="button" data-add-lesson>+ Přidat hodinu</button></div><p class="muted">Podle těchto hodin se počítá zelený a červený stav. Třídy zapiš např. 1.A; více tříd odděl čárkou. Učitel bez rozvrhu má stav „Bez rozvrhu“.</p><div class="table-wrap"><table class="lesson-table"><thead><tr><th>Den</th><th>Hodina</th><th>Třídy</th><th>Skupina</th><th>Předmět</th><th>Učebna</th><th></th></tr></thead><tbody id="lesson-rows">${t.schedule.map(lessonRow).join('')}</tbody></table></div></section><section class="panel form-stack"><h2>Podklady a poznámky</h2>${uploadField('pdf','Původní rozvrh PDF',t.pdf,'application/pdf')}${uploadField('scheduleSource','Fotografie rozvrhu',t.scheduleSource,'image/jpeg,image/png,image/webp')}${uploadField('video','Video v profilu',t.video,'video/mp4')}<label class="check-label"><input type="checkbox" name="videoEnabled" ${t.videoEnabled!==false?'checked':''}>Povolit video po otevření profilu</label><label>Náhradní avatar<select name="fallbackAvatar"><option value="male">Mimozemšťan · chlapec</option><option value="female" ${t.fallbackAvatar==='female'?'selected':''}>Mimozemšťanka · dívka</option></select></label>${field('bio','Další veřejné informace',t.bio,{area:true,max:5000,rows:4})}<div><div class="panel-head"><h2>Odkazy profilu</h2><button type="button" class="secondary" data-add-teacher-link>+ Přidat odkaz</button></div><p class="muted">Facebook, Instagram nebo web: ikona se vybere automaticky podle adresy a zobrazí se v seznamu i profilu učitele.</p><div id="teacher-links">${(t.externalLinks||[]).map(linkRow).join('')}</div></div>${field('duties','Pohotovosti a dohledy',t.duties,{area:true,rows:4,max:4000})}${field('teacherNote','Veřejná poznámka správce',state.content.teacherNotes[t.id]||'',{area:true,rows:5,max:5000,help:'Zobrazí se v profilu učitele. Osobní žákovské poznámky zůstávají oddělené.'})}${actions('Uložit profil a rozvrh')}</section></form>`}
function lessonRow(l={day:0,hour:0,classes:[],group:'',subject:'',room:''}){return `<tr data-lesson-row><td><select name="day" aria-label="Den">${['Pondělí','Úterý','Středa','Čtvrtek','Pátek'].map((day,i)=>`<option value="${i}" ${l.day===i?'selected':''}>${day}</option>`).join('')}</select></td><td><select name="hour" aria-label="Hodina">${Array.from({length:10},(_,i)=>`<option value="${i}" ${l.hour===i?'selected':''}>${i+1}.</option>`).join('')}</select></td><td><input class="class-input" name="classes" aria-label="Třídy" value="${esc((l.classes||[]).join(', '))}" maxlength="300" required></td><td><input name="group" aria-label="Skupina" value="${esc(l.group)}" maxlength="30"></td><td><input name="subject" aria-label="Předmět" value="${esc(l.subject)}" maxlength="40" required></td><td><input name="room" aria-label="Učebna" value="${esc(l.room)}" maxlength="80"></td><td><button class="text-button" type="button" data-remove-row aria-label="Odebrat hodinu">×</button></td></tr>`}
async function saveTeacher(form){const f=formObject(form),t={...activeTeacher,...f};delete t.teacherNote;t.videoEnabled=new FormData(form).has('videoEnabled');t.externalLinks=[...form.querySelectorAll('[data-link-row]')].map(row=>({label:row.querySelector('[name="label"]').value,url:row.querySelector('[name="url"]').value}));t.name=f.first.trim()+' '+f.last.trim();t.subjects=f.subjects.split(',').map(v=>v.trim()).filter(Boolean);t.schedule=$$('[data-lesson-row]').map(row=>{const value=name=>row.querySelector(`[name="${name}"]`).value;return{day:Number(value('day')),hour:Number(value('hour')),classes:value('classes').split(',').map(v=>v.trim().replace(/\s/g,'')).filter(Boolean),group:value('group'),subject:value('subject').trim(),room:value('room').trim()}});if(t.photo!==activeTeacher.photo){t.photoKind='circular-upload';t.photoUpdated=today()}const ts=clone(allTeachers());const i=ts.findIndex(v=>v.id===t.id);if(i<0)ts.push(t);else ts[i]=t;await saveContent({teachers:ts,teacherNotes:{...state.content.teacherNotes,[t.id]:f.teacherNote}},'teachers')}
function pagesList(){return title('Stránky a sekce.','Uprav obsah každé sekce nebo vytvoř novou stránku.',`<button class="primary" data-new-page>+ Nová stránka</button>`)+`<section class="panel"><h2>Stávající sekce webu</h2><div class="simple-list">${Object.entries(sectionNames).map(([id,label])=>{const section=state.content.sections[id]||{};return `<div class="simple-row"><div><strong>${esc(section.label||label)}</strong><p class="muted">${esc(section.description||'Texty, nadpisy, pořadí v menu a doplňující obsah.')}</p></div><span class="badge ${section.enabled!==false?'green':''}">${section.enabled!==false?'V menu':'Skrytá'}</span><button class="text-button" data-edit-section="${id}">Upravit →</button></div>`}).join('')}</div></section><section class="panel"><h2>Vlastní stránky</h2>${state.content.pages.length?`<div class="simple-list">${state.content.pages.map(p=>`<div class="simple-row"><div><strong>${esc(p.title)}</strong><p class="muted">#${esc(p.id)} · ${p.published?'zveřejněná':'koncept'}</p></div><button class="text-button" data-edit-page="${esc(p.id)}">Upravit</button><button class="text-button" data-delete-page="${esc(p.id)}">Odebrat</button></div>`).join('')}</div>`:'<div class="empty"><strong>Vlastní stránky si přidej podle potřeby.</strong>Například O škole, Studentská rada nebo Projekty.</div>'}</section>`}
function editSection(id){if(!discard())return;activeSection=id;const s=state.content.sections[id]||{};$('#workspace').innerHTML=title(esc(sectionNames[id])+'.','Uprav nadpis, text i zobrazení této sekce.',`<button class="secondary" data-go="pages">← Všechny sekce</button>`)+`<form id="section-form" class="panel"><div class="form-grid">${field('label','Název v menu',s.label||sectionNames[id],{max:45})}${field('order','Pořadí v menu',s.order??Object.keys(sectionNames).indexOf(id),{type:'number',max:3})}${field('title','Vlastní nadpis sekce',s.title,{max:180,full:true,help:id==='home'?'Úvodní nadpis a banner nastavíš ve Vzhled a nastavení.':'Prázdné pole zachová původní nadpis.'})}${field('description','Úvodní popis',s.description,{area:true,max:1000,rows:3,full:true})}${field('body','Doplňující obsah pod sekcí',s.body,{area:true,max:15000,rows:10,full:true})}<label class="check-label full"><input name="enabled" type="checkbox" ${s.enabled!==false?'checked':''} ${id==='home'?'disabled':''}>Zobrazovat sekci v menu</label><label class="check-label full"><input name="showNative" type="checkbox" ${s.showNative!==false?'checked':''}>Zobrazovat vestavěný obsah sekce</label><p class="muted full">Vypnutím vestavěného obsahu zobrazíš jen vlastní nadpis, text a dokumenty. Obsah můžeš později kdykoliv vrátit.</p></div>${actions('Uložit sekci',`<button type="button" class="secondary" data-go="documents">Připojit dokumenty →</button>`)}</form>`}
function editPage(id){if(!discard())return;activePage=clone(state.content.pages.find(p=>p.id===id)||{id:'page-'+uid(),label:'',title:'',body:'',image:'',published:false});const p=activePage;$('#workspace').innerHTML=title(id?'Upravit stránku.':'Nová vlastní stránka.','Zveřejněná stránka se automaticky objeví v hlavním menu.',`<button class="secondary" data-go="pages">← Všechny stránky</button>`)+`<form id="page-form" class="panel form-stack">${field('label','Krátký název v menu',p.label,{required:true,max:50})}${field('slug','Krátká adresa stránky',id?p.id.slice(5):'',{max:80,readonly:!!id,help:'Bez diakritiky a mezer, např. projekty. U nové stránky se prázdné pole doplní z názvu v menu.'})}${field('title','Nadpis stránky',p.title,{required:true,max:180})}${uploadField('image','Úvodní fotografie',p.image,'image/jpeg,image/png,image/webp')}${field('body','Obsah stránky',p.body,{area:true,rows:16,max:30000})}<label class="check-label"><input type="checkbox" name="published" ${p.published?'checked':''}>Zveřejnit stránku v menu</label>${actions('Uložit stránku')}</form>`}
function canEditExam(e){return owner()||e.author===me.username}
function examsView(){const exams=[...allExams()].sort((a,b)=>a.date.localeCompare(b.date));return title('Písemky v 1.A.','Společný přehled pro spolužáky. Redaktor upravuje své záznamy; hlavní administrátor všechny.',`<button class="primary" data-new-exam>+ Přidat písemku</button>`)+`<section class="panel"><div class="table-wrap"><table><thead><tr><th>Datum</th><th>Předmět a téma</th><th>Skupina / autor</th><th></th></tr></thead><tbody>${exams.map(e=>`<tr><td>${esc(e.date)}<div class="muted">${esc(e.time)}</div></td><td><strong>${esc(e.subject)} · ${esc(e.title)}</strong><div class="muted">${esc(e.notes)}</div></td><td>${esc(e.group||'Celá 1.A')}<div class="muted">${esc(e.authorName||e.author)}</div></td><td>${canEditExam(e)?`<div class="row-actions"><button class="text-button" data-edit-exam="${esc(e.id)}">Upravit</button><button class="text-button" data-delete-exam="${esc(e.id)}">Odebrat</button></div>`:'<span class="muted">Záznam jiného redaktora</span>'}</td></tr>`).join('')||'<tr><td colspan="4">Zatím nejsou zapsané žádné písemky.</td></tr>'}</tbody></table></div></section>`}
function editExam(id){if(!discard())return;activeExam=clone(allExams().find(e=>e.id===id)||{id:'pisemka-'+uid(),date:today(),subject:'',title:'',time:'',group:'',teacherId:'',notes:''});if(id&&!canEditExam(activeExam))return;const e=activeExam;$('#workspace').innerHTML=title(id?'Upravit písemku.':'Nová písemka v 1.A.','Po uložení ji uvidí spolužáci v kalendáři. Večer předem ji může připomenout upozornění.',`<button class="secondary" data-go="calendar">← Kalendář</button>`)+`<form id="exam-form" class="panel form-stack"><div class="form-grid">${field('date','Datum písemky',e.date,{required:true,type:'date'})}${field('subject','Předmět',e.subject,{required:true,max:60})}${field('title','Téma / název písemky',e.title,{required:true,max:200})}${field('time','Hodina nebo čas',e.time,{max:100})}${field('group','Skupina · prázdné = celá 1.A',e.group,{max:80})}<label>Vyučující<select name="teacherId"><option value="">Nevybrán</option>${allTeachers().map(t=>`<option value="${esc(t.id)}" ${t.id===e.teacherId?'selected':''}>${esc(t.name)}</option>`).join('')}</select></label></div>${field('notes','Podrobnosti · rozsah učiva, co přinést…',e.notes,{area:true,max:2000,rows:4})}${actions('Uložit a zveřejnit písemku')}</form>`}
async function saveExam(form){const result=await api({action:'exam_save',revision:state.revision,exam:{...activeExam,...formObject(form)}});state={...state,...result};dirty=false;await show('calendar',true);message('Písemka je uložená v kalendáři 1.A.','success')}
function calendarList(){if(!owner())return examsView();const es=allEvents();return examsView()+title('Školní kalendář.','Doplň akce, důležité termíny a volné dny. Svátky učitelů se doplňují každý rok automaticky podle českého kalendáře.',`<button class="primary" data-new-event>+ Nová událost</button>`)+`<section class="panel"><div class="toolbar"><input id="calendar-search" type="search" placeholder="Hledat v kalendáři…" aria-label="Hledat událost"><input type="month" id="calendar-month" aria-label="Vybrat měsíc"></div><div id="calendar-table">${eventTable(es)}</div></section>`}
function eventTable(){const q=($('#calendar-search')?.value||'').toLowerCase(),m=$('#calendar-month')?.value||'';const es=allEvents().filter(e=>e.title.toLowerCase().includes(q)&&(!m||e.date.startsWith(m)));return `<div class="table-wrap"><table><thead><tr><th>Datum</th><th>Událost</th><th>Typ</th><th></th></tr></thead><tbody>${es.map(e=>`<tr><td>${esc(e.date)}</td><td><strong>${esc(e.title)}</strong><div class="muted">${esc(e.time)}</div></td><td><span class="badge ${e.kind==='volno'?'blue':''}">${e.kind==='volno'?'Volný den':'Akce'}</span></td><td><div class="row-actions"><button class="text-button" data-edit-event="${esc(e.id)}">Upravit</button><button class="text-button" data-delete-event="${esc(e.id)}">Odebrat</button></div></td></tr>`).join('')}</tbody></table></div>`}
function editEvent(id){if(!discard())return;activeEvent=clone(allEvents().find(e=>e.id===id)||{id:'event-'+uid(),title:'',date:today(),time:'',kind:'akce'});const e=activeEvent;$('#workspace').innerHTML=title('Událost v kalendáři.','Volný den ovlivní také rozvrh a barevný stav učitelů.',`<button class="secondary" data-go="calendar">← Kalendář</button>`)+`<form id="event-form" class="panel form-stack">${field('title','Název události',e.title,{required:true,max:250})}<div class="form-grid">${field('date','Datum',e.date,{required:true,type:'date'})}${field('time','Čas nebo upřesnění',e.time,{max:100})}</div><label>Typ<select name="kind"><option value="akce">Školní akce</option><option value="volno" ${e.kind==='volno'?'selected':''}>Volný den / prázdniny</option></select></label>${actions('Uložit událost')}</form>`}
function roomsList(){const names=new Set([...allTeachers().map(t=>t.room),...allTeachers().flatMap(t=>t.schedule.map(l=>l.room)),...state.content.rooms.map(r=>r.name)].filter(Boolean));return title('Učebny a kabinety.','Doplň patro a popis místností. Rozvrhy se upravují u vyučujících.',`<button class="primary" data-new-room>+ Přidat místnost</button>`)+`<section class="panel"><div class="table-wrap"><table><thead><tr><th>Místnost</th><th>Patro</th><th>Popis</th><th></th></tr></thead><tbody>${[...names].sort((a,b)=>a.localeCompare(b,'cs',{numeric:true})).map(name=>{const r=state.content.rooms.find(r=>r.name===name);return `<tr><td><strong>${esc(name)}</strong></td><td>${esc(r?.floor||'Nedoplněno')}</td><td>${esc(r?.description?.slice(0,100)||'—')}</td><td><button class="text-button" data-edit-room="${esc(name)}">Upravit</button></td></tr>`}).join('')}</tbody></table></div></section>`}
function editRoom(name){if(!discard())return;activeRoom=clone(state.content.rooms.find(r=>r.name===name)||{id:'room-'+uid(),name:name||'',floor:'',description:''});const r=activeRoom;$('#workspace').innerHTML=title('Podrobnosti místnosti.','Doplň ověřené umístění nebo informace pro návštěvníky.',`<button class="secondary" data-go="rooms">← Místnosti</button>`)+`<form id="room-form" class="panel form-stack">${field('name','Označení místnosti',r.name,{max:80,required:true})}${field('floor','Patro',r.floor,{max:80})}${field('description','Popis',r.description,{area:true,max:3000,rows:6})}${actions('Uložit místnost',`<button type="button" class="danger" data-delete-room="${esc(r.id)}">Odebrat doplněné údaje</button>`)}</form>`}
function documentsList(){return title('Dokumenty a podklady.','Nahraj soubory a připoj je k libovolné sekci webu.',`<button class="primary" data-new-document>+ Přidat dokument</button>`)+`<section class="panel">${state.content.documents.length?`<div class="simple-list">${state.content.documents.map(d=>`<div class="simple-row"><div><strong>${esc(d.title)}</strong><p class="muted">${esc(sectionNames[d.section])} · ${esc(d.description)}</p></div><a class="text-button" href="${esc(d.url)}" target="_blank" rel="noopener">Otevřít ↗</a><button class="text-button" data-edit-document="${esc(d.id)}">Upravit</button><button class="text-button" data-delete-document="${esc(d.id)}">Odebrat</button></div>`).join('')}</div>`:'<div class="empty"><strong>Zatím nejsou připojené další dokumenty.</strong>Původní podklady rozvrhů a půdorysu zůstávají na webu dostupné.</div>'}</section>`}
function editDocument(id){if(!discard())return;activeDocument=clone(state.content.documents.find(d=>d.id===id)||{id:'doc-'+uid(),title:'',description:'',url:'',section:'sources'});const d=activeDocument;$('#workspace').innerHTML=title('Dokument na webu.','Soubor se po uložení zobrazí v určené sekci.',`<button class="secondary" data-go="documents">← Dokumenty</button>`)+`<form id="document-form" class="panel form-stack">${field('title','Název dokumentu',d.title,{required:true,max:150})}${uploadField('url','Soubor nebo HTTPS odkaz',d.url,'image/jpeg,image/png,image/webp,application/pdf,video/mp4')}${field('description','Krátký popis',d.description,{area:true,max:1000,rows:3})}<label>Zobrazit v sekci<select name="section">${Object.entries(sectionNames).map(([id,name])=>`<option value="${id}" ${d.section===id?'selected':''}>${name}</option>`).join('')}</select></label>${actions('Uložit dokument')}</form>`}
let pushTestId='';
function notificationSettings(){return `<section class="panel push-test-settings"><div class="panel-head"><h2>Upozornění a sváteční přání</h2><span class="badge">Pouze kubicek</span></div><p class="muted">Zkontroluj vzhled přání nebo pošli označené testovací upozornění všem aktivním odběratelům. Také tvoje zařízení musí mít odběr povolený ve zvonku na veřejném webu.</p><div class="row-actions"><button class="secondary" type="button" data-preview-celebration>Náhled svátečního přání</button><button class="primary" type="button" data-open-push-test>Testovat notifikace všem</button></div><p class="muted">Výsledek ukazuje přijetí push službou. Skutečné zobrazení ověří příjemce na telefonu. Test lze poslat nejvýše jednou za minutu.</p></section>`}
async function previewPushTest(){if(!owner())return;const info=await api({action:'push_test_info'});pushTestId=uid();modal('Testovací upozornění',`<section class="push-test-dialog"><h2>Vyzkoušet upozornění na telefonech.</h2><p>Pošleme zprávu <strong>„Betlémská · test upozornění“</strong> všem <strong>${info.total} aktivním zařízením</strong>, včetně tvého telefonu, pokud máš odběr zapnutý.</p>${info.diagnostics?`<div class="notice"><strong>Připojené služby</strong><p>${Object.entries(info.diagnostics.providers).map(([name,p])=>esc(name)+': '+p.active+' aktivních / '+p.total+' celkem').join(' · ')||'Žádné připojené zařízení'}</p>${info.diagnostics.lastDeliveries.filter(d=>!d.accepted).length?`<p>Poslední nepřijaté zprávy: ${info.diagnostics.lastDeliveries.filter(d=>!d.accepted).map(d=>esc(d.provider)+' · '+esc(d.reason)+' · HTTP '+d.status).join('; ')}</p>`:''}</div>`:''}${info.paused?`<p class="muted">${info.paused} zařízení má všechny kategorie vypnuté a test nedostane.</p>`:''}${info.legacy?`<p class="muted">${info.legacy} starších odběrů používá základní doručení. Běžná návštěva webu jejich připojení automaticky aktualizuje.</p>`:''}${info.lastTest?`<div class="push-last-test"><strong>Poslední test · ${stamp(info.lastTest.createdAt)}</strong><p>${esc(describePushTest(info.lastTest))}</p><button class="text-button" type="button" data-refresh-push-test="${esc(info.lastTest.id)}">Obnovit výsledek posledního testu</button></div>`:''}<p id="push-test-result" role="status" aria-live="polite">${info.total?'Připraveno k odeslání.':'Nejdřív zapni odběr přes zvonek Upozornění na veřejném webu.'}</p><button class="primary" type="button" data-send-push-test ${info.total?'':'disabled'}>Odeslat test všem ${info.total} zařízením</button><p class="muted">Když zpráva nepřijde, zkontroluj povolení oznámení, režim soustředění a na iPhonu otevření aplikace z plochy.</p></section>`)}
function describePushTest(t){if(t.status==='queued'||t.status==='sending')return 'Odesílám test…';return `Push služba přijala ${t.accepted} z ${t.total} zpráv. Nepřijatých: ${t.failed}. ${t.status==='failed'?'Běh skončil chybou. ':''}Doručení ověř na telefonu.`}
async function sendPushTest(){if(!owner()||!pushTestId)return;const id=pushTestId,button=$('[data-send-push-test]');if(button)button.disabled=true;let result;try{result=await api({action:'push_test_send',id,confirm:true});for(let i=0;i<32;i++){const status=$('#push-test-result');if(!status)return;status.textContent=describePushTest(result.test);if(!['queued','sending'].includes(result.test.status))return;await new Promise(resolve=>setTimeout(resolve,1000));result=await api({action:'push_test_status',id})}if($('#push-test-result'))$('#push-test-result').textContent='Test se ještě zpracovává. Neodesílej ho znovu; výsledek můžeš později znovu načíst.';}catch(e){if($('#push-test-result'))$('#push-test-result').textContent=e.message||'Odeslání se nepodařilo ověřit.';if(button?.isConnected)button.disabled=false}}
function settingsView(){const s=state.content.settings;return title('Vzhled a nastavení.','Identita webu, hlavní stránka, horní část a užitečné odkazy.')+`<form id="settings-form"><section class="panel"><h2>Identita a kontakt</h2><div class="form-grid">${field('siteTitle','Název webu / titul stránky',s.siteTitle,{max:100,help:'Např. Betlémská · školní portál'})}${field('subtitle','Popisek pod logem',s.subtitle,{max:140})}${field('address','Škola a adresa v postranním panelu',s.address,{max:200,full:true})}${field('footer','Text v patičce',s.footer,{max:400,full:true})}<label>Barva akcentu<div class="color-row"><input name="accent" type="color" value="${esc(s.accent||'#1f8cc7')}"><span class="muted">Zachová se šedý základ webu.</span></div></label></div></section><section class="panel form-stack"><h2>Logo a hlavní fotografie</h2>${uploadField('logo','Logo školy',s.logo,'image/jpeg,image/png,image/webp','Prázdné pole zachová stávající školní logo.')}${uploadField('heroImage','Fotografie úvodního banneru',s.heroImage,'image/jpeg,image/png,image/webp','Prázdné pole zachová fotografii budovy.')}</section><section class="panel"><h2>Hlavní stránka</h2><div class="form-grid">${field('homeTitle','Hlavní nadpis',s.homeTitle,{area:true,rows:2,max:150})}${field('intro','Úvodní odstavec',state.content.intro,{area:true,rows:3,max:600})}${field('heroTitle','Nadpis banneru',s.heroTitle,{area:true,rows:2,max:180})}${field('heroText','Text banneru',s.heroText,{area:true,rows:3,max:600})}</div><p class="muted">Prázdné texty zachovají současné znění.</p><div class="check-grid">${[['showDay','Školní den'],['showLunch','Dnešní oběd'],['showFavorites','Moje oblíbené']].map(([id,label])=>`<label class="check-label"><input type="checkbox" name="${id}" ${s[id]!==false?'checked':''}>${label}</label>`).join('')}</div></section><section class="panel"><div class="panel-head"><h2>Další užitečné odkazy</h2><button type="button" class="secondary" data-add-link>+ Odkaz</button></div><div id="settings-links">${state.content.links.map(linkRow).join('')}</div>${actions('Uložit vzhled a nastavení')}</section></form>`+notificationSettings()}
function linkRow(l={label:'',url:''}){return `<div class="link-row" data-link-row>${BetlemskaTeacherLinks.preview(l)}${field('label','Název',l.label,{required:true,max:100})}${field('url','HTTPS adresa',l.url,{required:true,type:'url',max:1500})}<button type="button" class="text-button" data-remove-row>Odebrat ×</button></div>`}
async function mediaView(){const r=await fetch(new URL('api/media',document.baseURI),{cache:'no-store',credentials:'same-origin',signal:AbortSignal.timeout(15000)});const data=await r.json();if(!r.ok)throw Error(data.error||'Mediatéku nelze načíst.');media=data.media;return title('Mediatéka.','Fotografie JPG, PNG, WebP, dokumenty PDF a videa MP4 do 8 MB. Soubory můžeš znovu používat v obsahu.',`<button class="primary" data-upload="library" data-accept="image/jpeg,image/png,image/webp,application/pdf,video/mp4">+ Nahrát soubor</button>`)+`<div class="notice">Nahrání uloží soubor a vytvoří jeho veřejný odkaz. Do stránky nebo profilu ho připojíš uložením příslušné úpravy.</div><div class="media-grid">${media.map(m=>`<article class="media-item">${m.mime.startsWith('image/')?`<img src="api/media/${esc(m.id)}" alt="${esc(m.name)}" loading="lazy">`:`<div class="media-file">${m.mime.startsWith('video/')?'VIDEO':'PDF'}</div>`}<div class="media-info"><strong>${esc(m.name)}</strong><small>${(m.size/1024).toFixed(0)} kB · ${esc(m.created_by)}</small><input readonly aria-label="Odkaz na ${esc(m.name)}" value="${esc(new URL('api/media/'+m.id,document.baseURI).href)}"><button class="text-button" data-copy-media="${esc(m.id)}">Kopírovat odkaz</button></div></article>`).join('')||'<div class="empty">Zatím žádné nahrané soubory.</div>'}</div>`}
async function usersView(){const result=await api({action:'users'});return title('Redakce a účty.','Přidávej redaktory a spravuj jejich přístup. Hlavní administrátor má plná oprávnění.',`<button class="primary" data-new-user>+ Přidat redaktora</button>`)+`<section class="panel"><div class="table-wrap"><table><thead><tr><th>Uživatel</th><th>Role</th><th>Stav</th><th></th></tr></thead><tbody>${result.users.map(u=>`<tr><td><strong>${esc(u.display_name||u.username)}</strong><div class="muted">${esc(u.username)}</div></td><td><span class="badge ${u.role==='admin'?'blue':''}">${u.role==='admin'?'Hlavní administrátor':'Redaktor'}</span></td><td><span class="badge ${u.active?'green':'red'}">${u.active?'Aktivní':'Deaktivovaný'}</span></td><td>${u.username==='kubicek'?'<button class="text-button" data-go="account">Můj účet →</button>':`<button class="text-button" data-edit-user="${esc(u.username)}">Upravit přístup</button>`}</td></tr>`).join('')}</tbody></table></div></section><section class="panel"><h2>Rozdělení oprávnění</h2><div class="table-wrap"><table><thead><tr><th>Možnost</th><th>Ty · administrátor</th><th>Redaktor</th></tr></thead><tbody>${[['Aktuality a koncepty','Všechny','Vlastní články'],['Nahrávání médií','Ano','Ano'],['Učitelé, rozvrhy a stránky','Ano','—'],['Vzhled, kalendář a dokumenty','Ano','—'],['Účty, historie a obnova','Ano','—']].map(row=>`<tr>${row.map(v=>`<td>${v}</td>`).join('')}</tr>`).join('')}</tbody></table></div></section>`}
async function editUser(username){if(!discard())return;const r=await api({action:'users'});activeUser=r.users.find(u=>u.username===username)||null;const u=activeUser;$('#workspace').innerHTML=title(u?'Přístup redaktora.':'Nový člen redakce.','Redaktor bude mít přístup ke svým aktualitám a k mediatéce.',`<button class="secondary" data-go="users">← Redakce</button>`)+`<form id="user-form" class="panel form-stack">${field('username','Uživatelské jméno',u?.username||'',{required:true,max:40,readonly:!!u,help:'3–40 znaků, malé písmo, čísla, podtržítko nebo pomlčka; bez diakritiky.'})}${field('displayName','Zobrazované jméno',u?.display_name||'',{required:true,max:100})}${field('password',u?'Nové heslo · volitelné':'Počáteční heslo','',{type:'password',required:!u,min:12,max:256,help:u?'Vyplněním změníš heslo. Uložení přístupu také ukončí současná přihlášení redaktora.':'Nejméně 12 znaků. Údaje předáš redaktorovi sám; web neposílá pozvánky.'})}${u?`<label class="check-label"><input type="checkbox" name="active" ${u.active?'checked':''}>Účet je aktivní</label>`:''}${actions(u?'Uložit přístup':'Vytvořit účet redaktora')}</form>`}
async function historyView(){const r=await api({action:'history'});return title('Historie a záloha.','Vrať obsah do předchozí podoby nebo si stáhni jeho kopii.')+`<section class="panel"><h2>Záloha obsahu</h2><p class="muted">Export obsahuje texty, učitele, rozvrhy, odkazy a nastavení. Neobsahuje hesla ani samotné nahrané soubory; jejich odkazy zůstávají spojené s tímto webem.</p><div class="backup-actions"><button class="primary" data-export>Stáhnout obsah JSON</button><button class="secondary" data-import>Obnovit z JSON</button></div></section><section class="panel"><h2>Verze obsahu</h2><p class="muted">Obnova vytvoří novou verzi, takže se můžeš vrátit i k současnému stavu. Účty a hesla se obnovou obsahu nemění.</p>${r.versions.length?`<div class="table-wrap"><table><thead><tr><th>Verze</th><th>Uloženo</th><th>Autor</th><th></th></tr></thead><tbody>${r.versions.map(v=>`<tr><td><strong>#${v.revision}</strong></td><td>${stamp(v.created_at)}</td><td>${esc(v.actor)}</td><td>${v.revision===state.revision?'<span class="badge green">Současná</span>':`<button class="text-button" data-restore="${v.revision}">Obnovit verzi</button>`}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Historie se začne ukládat při první úpravě v nové administraci.</div>'}</section><section class="panel"><h2>Záznam správy</h2>${r.audit.length?`<div class="simple-list">${r.audit.map(a=>`<div class="simple-row"><div><strong>${esc(({user_create:'Vytvořen účet',user_update:'Změněn přístup',restore:'Obnoven obsah'})[a.action]||a.action)} · ${esc(a.detail)}</strong><p class="muted">${stamp(a.created_at)} · ${esc(a.actor)}</p></div></div>`).join('')}</div>`:'<p class="muted">Zatím žádné změny účtů nebo obnovení.</p>'}</section>`}
function accountView(){return title('Můj účet.','Přihlášení, role a změna hesla.')+`<div class="two-col"><section class="panel"><h2>Změnit heslo</h2><p class="muted">Změna odhlásí všechna tvoje zařízení. Potom se přihlas novým heslem.</p><form id="password-form" class="form-stack">${field('currentPassword','Současné heslo','',{type:'password',required:true,max:256})}${field('newPassword','Nové heslo','',{type:'password',required:true,min:12,max:256,help:'Nejméně 12 znaků.'})}${field('confirmation','Nové heslo znovu','',{type:'password',required:true,min:12,max:256})}${actions('Změnit heslo')}</form></section><section class="panel"><h2>Přihlášený účet</h2><p><strong>${esc(me.displayName||me.username)}</strong></p><p class="muted">Uživatelské jméno: ${esc(me.username)}<br>Role: ${owner()?'Hlavní administrátor':'Redaktor'}<br>Přihlášení platí nejvýše 12 hodin.</p><button class="secondary" data-logout>Odhlásit toto zařízení</button></section></div>`}
function discard(){if(dirty&&!confirm('Zahodit neuložené změny a otevřít jinou položku?'))return false;dirty=false;message();return true}
function modal(label,body){$('#dialog-label').textContent=label;$('#dialog-body').innerHTML=body;$('#admin-modal').showModal()}
function closeModal(){if(cropObjectURL){URL.revokeObjectURL(cropObjectURL);cropObjectURL=''}cropImage=null;$('#admin-modal').close()}
async function upload(file){if(file.size>8*1024*1024)throw Error('Soubor může mít maximálně 8 MB.');message('Nahrávám soubor…');const response=await fetch(new URL('api/media',document.baseURI),{method:'POST',credentials:'same-origin',headers:{'X-Portal-Action':'1','Content-Type':file.type||'application/octet-stream','X-File-Name':encodeURIComponent(file.name||'fotografie.webp')},body:file,signal:AbortSignal.timeout(45000)});let result;try{result=await response.json()}catch{throw Error('Soubor se nepodařilo uložit. Zkus ho nahrát znovu.')}if(!response.ok)throw Error(result.error||'Nahrání se nezdařilo.');return result}
async function cropTeacher(file){if(!file.type.startsWith('image/'))throw Error('Vyber fotografii.');if(file.size>8*1024*1024)throw Error('Fotografie může mít nejvýše 8 MB.');cropName=file.name;cropObjectURL=URL.createObjectURL(file);const image=new Image();image.src=cropObjectURL;await image.decode();cropImage=image;modal('PORTRÉT VYUČUJÍCÍHO',`<p class="muted">Nastav výřez na obličej. Posuvníky mění přiblížení a polohu snímku.</p><canvas class="crop-canvas" id="crop-canvas" width="512" height="512" aria-label="Náhled kruhového portrétu"></canvas><div class="crop-sliders"><label>Přiblížení<input id="crop-zoom" type="range" min="100" max="350" value="100"></label><label>Vodorovná poloha<input id="crop-x" type="range" min="0" max="100" value="50"></label><label>Svislá poloha<input id="crop-y" type="range" min="0" max="100" value="50"></label></div><div class="form-actions"><button class="secondary" data-close-modal>Zrušit</button><button class="primary" data-save-crop>Použít portrét</button></div>`);drawCrop()}
function drawCrop(){if(!cropImage)return;const canvas=$('#crop-canvas'),ctx=canvas.getContext('2d');const scale=Math.max(512/cropImage.naturalWidth,512/cropImage.naturalHeight)*Number($('#crop-zoom').value)/100,w=cropImage.naturalWidth*scale,h=cropImage.naturalHeight*scale;ctx.clearRect(0,0,512,512);ctx.save();ctx.beginPath();ctx.arc(256,256,256,0,Math.PI*2);ctx.clip();ctx.drawImage(cropImage,(512-w)*Number($('#crop-x').value)/100,(512-h)*Number($('#crop-y').value)/100,w,h);ctx.restore()}
function updateTeacherPhoto(url){$('#field-photo').value=url;const old=$('#teacher-photo-preview');const element=document.createElement(url?'img':'span');element.id='teacher-photo-preview';element.className='teacher-photo large';if(url){element.src=url;element.alt='Portrét vyučujícího'}else element.textContent='—';old.replaceWith(element);mark()}
async function chooseMedia(target,accept){const r=await fetch(new URL('api/media',document.baseURI),{cache:'no-store',credentials:'same-origin',signal:AbortSignal.timeout(15000)});const data=await r.json();if(!r.ok)throw Error(data.error||'Mediatéku nelze načíst.');const files=data.media.filter(m=>accept.split(',').includes(m.mime)||(accept.includes('image/*')&&m.mime.startsWith('image/')));modal('VYBRAT Z MEDIATÉKY',`<div class="media-grid">${files.map(m=>`<button class="media-item media-choice" data-use-media="${esc(m.id)}" data-for-field="${esc(target)}">${m.mime.startsWith('image/')?`<img src="api/media/${esc(m.id)}" alt="${esc(m.name)}" loading="lazy">`:`<span class="media-file">${m.mime.startsWith('video/')?'VIDEO':'PDF'}</span>`}<span class="media-info">${esc(m.name)}</span></button>`).join('')||'<p class="muted">Zatím nemáš nahraný soubor tohoto typu. Zavři okno a použij Nahrát soubor.</p>'}</div>`)}
function setMediaField(target,url){const input=document.getElementById(target);if(!input)return;input.value=url;mark();if(target==='field-cover'){const old=$('#post-image-preview'),img=document.createElement('img');img.id='post-image-preview';img.className='image-preview';img.src=url;img.alt='Náhled fotografie';old.replaceWith(img)}}
function previewPost(){const p=collectPost();modal('NÁHLED AKTUALITY · ZATÍM NEZVEŘEJNĚNO',`<article class="preview-article ${p.cover?'has-cover':''}">${p.cover?`<img src="${esc(p.cover)}" alt="${esc(p.title)}">`:''}<div class="preview-copy"><span class="badge blue">${esc(p.category)}</span><h2>${esc(p.title||'Bez nadpisu')}</h2>${p.excerpt?`<p><strong>${esc(p.excerpt)}</strong></p>`:''}<p>${esc(p.body)}</p></div></article>`)}
$('#login-form').addEventListener('submit',e=>{e.preventDefault();const form=e.target;run(async()=>{const f=formObject(form),r=await api({action:'login',...f});form.reset();await initSession(r)})});
$('#workspace').addEventListener('input',e=>{if(e.target.id==='teacher-admin-search'){$('#teacher-admin-table').innerHTML=teachersTable();return}if(e.target.id==='news-search'){$('#news-table').innerHTML=newsTable();return}if(['calendar-search','calendar-month'].includes(e.target.id)){$('#calendar-table').innerHTML=eventTable();return}if(e.target.closest('form'))mark()});
$('#workspace').addEventListener('change',e=>{if(e.target.id==='news-filter')$('#news-table').innerHTML=newsTable();if(e.target.id==='calendar-month')$('#calendar-table').innerHTML=eventTable();if(e.target.closest('form'))mark()});
$('#workspace').addEventListener('submit',e=>{e.preventDefault();const form=e.target;run(async()=>{const f=formObject(form);if(form.id==='post-form')return savePost('published');if(form.id==='exam-form')return saveExam(form);if(form.classList.contains('report-manage-form')){await api({action:'report_update',id:form.dataset.id,revision:Number(form.dataset.revision),status:f.status,note:f.note});await show('reports',true);message('Podnět je aktualizovaný.','success');return}if(form.id==='teacher-form')return saveTeacher(form);if(form.id==='section-form')return saveContent({sections:{...state.content.sections,[activeSection]:{...f,enabled:activeSection==='home'||new FormData(form).has('enabled'),showNative:new FormData(form).has('showNative'),order:Number(f.order)}}},'pages');if(form.id==='page-form'){const pages=clone(state.content.pages),existing=pages.some(v=>v.id===activePage.id);const item={...activePage,...f,id:existing?activePage.id:'page-'+slugify(f.slug||f.label),published:new FormData(form).has('published')};if(!existing&&pages.some(v=>v.id===item.id))throw Error('Tato adresa stránky už existuje. Zvol jinou.');const i=pages.findIndex(v=>v.id===item.id);if(i<0)pages.push(item);else pages[i]=item;return saveContent({pages},'pages')}if(form.id==='event-form'){const events=clone(allEvents()),item={...activeEvent,...f},i=events.findIndex(v=>v.id===item.id);if(i<0)events.push(item);else events[i]=item;return saveContent({events},'calendar')}if(form.id==='room-form'){const rooms=clone(state.content.rooms),item={...activeRoom,...f},i=rooms.findIndex(v=>v.id===item.id);if(i<0)rooms.push(item);else rooms[i]=item;return saveContent({rooms},'rooms')}if(form.id==='document-form'){const documents=clone(state.content.documents),item={...activeDocument,...f},i=documents.findIndex(v=>v.id===item.id);if(i<0)documents.push(item);else documents[i]=item;return saveContent({documents},'documents')}if(form.id==='settings-form'){const settings={};for(const key of ['siteTitle','subtitle','address','footer','accent','logo','heroImage','homeTitle','heroTitle','heroText'])settings[key]=f[key];for(const key of ['showDay','showLunch','showFavorites'])settings[key]=new FormData(form).has(key);const links=$$('[data-link-row]').map(row=>({label:row.querySelector('[name="label"]').value,url:row.querySelector('[name="url"]').value}));return saveContent({settings,intro:f.intro,links},'settings')}if(form.id==='user-form'){await api({action:activeUser?'user_update':'user_create',...f,active:new FormData(form).has('active')});dirty=false;await show('users',true);message(activeUser?'Přístup redaktora je upravený.':'Účet redaktora je vytvořený.','success');return}if(form.id==='password-form'){if(f.newPassword!==f.confirmation)throw Error('Nová hesla se neshodují.');await api({action:'password',currentPassword:f.currentPassword,newPassword:f.newPassword});dirty=false;form.reset();showLogin('Heslo je změněné. Přihlas se novým heslem.')}})});
document.addEventListener('click',e=>{const el=e.target.closest('button');if(!el)return;if(el.hasAttribute('data-preview-celebration')){if(!owner())return;const teachers=allTeachers(),date=today(),C=window.BetlemskaCalendar,todayTeachers=teachers.filter(t=>C?.nameDays[t.first]===date.slice(5));if(window.BetlemskaCelebrations)window.BetlemskaCelebrations.preview(todayTeachers.length?todayTeachers:teachers.slice(0,1),date,id=>editTeacher(id));else message('Náhled není načtený. Obnov stránku.','error');return}if(el.hasAttribute('data-open-push-test')){run(previewPushTest);return}if(el.hasAttribute('data-refresh-push-test')){run(async()=>{const result=await api({action:'push_test_status',id:el.dataset.refreshPushTest});if($('#push-test-result'))$('#push-test-result').textContent=describePushTest(result.test)});return}if(el.hasAttribute('data-send-push-test')){run(sendPushTest);return}if(el.hasAttribute('data-report-filter')){reportFilter=el.dataset.reportFilter;reportOffset=0;run(()=>show('reports',true));return}if(el.hasAttribute('data-report-offset')){reportOffset=Number(el.dataset.reportOffset);run(()=>show('reports',true));return}if(el.hasAttribute('data-menu')){document.body.classList.toggle('menu-open');return}if(el.hasAttribute('data-close-modal')){closeModal();return}if(el.dataset.go){run(()=>show(el.dataset.go));return}if(el.dataset.chooseMedia){run(()=>chooseMedia(el.dataset.chooseMedia,el.dataset.accept||''));return}if(el.dataset.useMedia){setMediaField(el.dataset.forField,'/api/media/'+el.dataset.useMedia);closeModal();message('Soubor vybrán. Potvrď změnu uložením formuláře.','success');return}if(el.hasAttribute('data-new-post')){page='news';renderNav();editPost();return}if(el.dataset.editPost){editPost(el.dataset.editPost);return}if(el.dataset.saveNews){run(()=>savePost(el.dataset.saveNews));return}if(el.hasAttribute('data-preview-post')){previewPost();return}if(el.dataset.deletePost){run(async()=>{if(!confirm('Odebrat tuto aktualitu? Administrátor může obsah obnovit z historie.'))return;const r=await api({action:'news_delete',id:el.dataset.deletePost,revision:state.revision});state={...state,...r};await show('news',true);message('Aktualita odebrána.','success')});return}if(el.hasAttribute('data-new-teacher')){editTeacher();return}if(el.dataset.editTeacher){editTeacher(el.dataset.editTeacher);return}if(el.dataset.deleteTeacher){run(async()=>{if(!confirm('Odebrat profil učitele včetně jeho rozvrhu z webu?'))return;const teacherNotes={...state.content.teacherNotes};delete teacherNotes[el.dataset.deleteTeacher];await saveContent({teachers:allTeachers().filter(t=>t.id!==el.dataset.deleteTeacher),teacherNotes},'teachers')});return}if(el.hasAttribute('data-add-lesson')){$('#lesson-rows').insertAdjacentHTML('beforeend',lessonRow());mark();return}if(el.hasAttribute('data-remove-row')){el.closest('[data-lesson-row],[data-link-row]').remove();mark();return}if(el.hasAttribute('data-new-page')){editPage();return}if(el.dataset.editPage){editPage(el.dataset.editPage);return}if(el.dataset.editSection){editSection(el.dataset.editSection);return}if(el.dataset.deletePage){run(async()=>{if(confirm('Odebrat tuto stránku z webu?'))await saveContent({pages:state.content.pages.filter(p=>p.id!==el.dataset.deletePage)},'pages')});return}if(el.hasAttribute('data-new-exam')){editExam();return}if(el.dataset.editExam){editExam(el.dataset.editExam);return}if(el.dataset.deleteExam){run(async()=>{if(!confirm('Odebrat tuto písemku z kalendáře?'))return;const result=await api({action:'exam_delete',revision:state.revision,id:el.dataset.deleteExam});state={...state,...result};dirty=false;await show('calendar',true);message('Písemka byla odebrána.','success')});return}if(el.hasAttribute('data-new-event')){editEvent();return}if(el.dataset.editEvent){editEvent(el.dataset.editEvent);return}if(el.dataset.deleteEvent){run(async()=>{if(confirm('Odebrat událost z kalendáře?'))await saveContent({events:allEvents().filter(v=>v.id!==el.dataset.deleteEvent)},'calendar')});return}if(el.hasAttribute('data-new-room')){editRoom();return}if(el.hasAttribute('data-edit-room')){editRoom(el.dataset.editRoom);return}if(el.dataset.deleteRoom){run(async()=>{if(confirm('Odebrat doplněný popis této místnosti? Místnost zůstane, pokud se vyskytuje v rozvrhu.'))await saveContent({rooms:state.content.rooms.filter(v=>v.id!==el.dataset.deleteRoom)},'rooms')});return}if(el.hasAttribute('data-new-document')){editDocument();return}if(el.dataset.editDocument){editDocument(el.dataset.editDocument);return}if(el.dataset.deleteDocument){run(async()=>{if(confirm('Odebrat dokument ze sekce webu? Nahraný soubor zůstane v mediatéce.'))await saveContent({documents:state.content.documents.filter(v=>v.id!==el.dataset.deleteDocument)},'documents')});return}if(el.hasAttribute('data-add-teacher-link')){$('#teacher-links').insertAdjacentHTML('beforeend',linkRow());mark();return}if(el.hasAttribute('data-add-link')){$('#settings-links').insertAdjacentHTML('beforeend',linkRow());mark();return}if(el.hasAttribute('data-new-user')){run(()=>editUser());return}if(el.dataset.editUser){run(()=>editUser(el.dataset.editUser));return}if(el.dataset.restore){run(async()=>{if(!confirm('Obnovit veškerý obsah z verze #'+el.dataset.restore+'? Současný stav zůstane v historii.'))return;const r=await api({action:'restore',targetRevision:Number(el.dataset.restore),revision:state.revision});state={...state,...r};await show('history',true);message('Obsah byl obnoven.','success')});return}if(el.hasAttribute('data-export')){const blob=new Blob([JSON.stringify({schemaVersion:2,exportedAt:new Date().toISOString(),content:state.content},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='betlemska-obsah-'+today()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return}if(el.hasAttribute('data-import')){$('#import-picker').click();return}if(el.hasAttribute('data-logout')){run(async()=>{if(dirty&&!confirm('Odhlásit se a zahodit neuložené změny?'))return;await api({action:'logout'});dirty=false;showLogin('Jsi odhlášený.')});return}if(el.hasAttribute('data-crop-teacher')){uploadTarget='crop';$('#media-picker').accept='image/jpeg,image/png,image/webp';$('#media-picker').value='';$('#media-picker').click();return}if(el.hasAttribute('data-remove-photo')){updateTeacherPhoto('');return}if(el.hasAttribute('data-upload')){uploadTarget=el.dataset.upload;$('#media-picker').accept=el.dataset.accept||'image/jpeg,image/png,image/webp,application/pdf,video/mp4';$('#media-picker').value='';$('#media-picker').click();return}if(el.hasAttribute('data-save-crop')){run(async()=>{el.disabled=true;try{const blob=await new Promise(resolve=>$('#crop-canvas').toBlob(resolve,'image/webp',.92));if(!blob)throw Error('Výřez fotografie se nepodařil.');const file=new File([blob],cropName.replace(/\.[^.]+$/,'')+'-portret.webp',{type:'image/webp'});const result=await upload(file);updateTeacherPhoto(result.url);closeModal();message('Portrét je nahraný. Potvrď ho uložením profilu.','success')}finally{el.disabled=false}});return}if(el.dataset.copyMedia){run(async()=>{const url=new URL('api/media/'+el.dataset.copyMedia,document.baseURI).href;try{await navigator.clipboard.writeText(url);message('Odkaz zkopírován.','success')}catch{const input=el.closest('.media-info').querySelector('input');input.select();message('Odkaz je označený. Zkopíruj ho pomocí Ctrl/Cmd+C.')}})}});
$('#media-picker').addEventListener('change',e=>{const file=e.target.files?.[0];if(!file)return;run(async()=>{if(uploadTarget==='crop')return cropTeacher(file);const result=await upload(file);if(uploadTarget==='library'){await show('media',true);message('Soubor je uložený v mediatéce.','success')}else{const input=document.getElementById(uploadTarget);if(input){input.value=result.url;mark();message('Soubor nahrán. Potvrď změnu uložením formuláře.','success');if(uploadTarget==='field-cover'){const old=$('#post-image-preview'),img=document.createElement('img');img.id='post-image-preview';img.className='image-preview';img.src=result.url;img.alt='Náhled fotografie';old.replaceWith(img)}}}})});
$('#import-picker').addEventListener('change',e=>{const file=e.target.files?.[0];if(!file)return;run(async()=>{if(file.size>1800000)throw Error('Záloha může mít nejvýše 1,8 MB.');let data;try{data=JSON.parse(await file.text())}catch{throw Error('Neplatný JSON soubor.')}if(!data.content)throw Error('V souboru chybí obsah rozcestníku.');if(!confirm('Nahradit současný obsah touto zálohou? Současný stav zůstane v historii.'))return;await saveContent(data.content,'history')})});
$('#dialog-body').addEventListener('input',e=>{if(e.target.id.startsWith('crop-'))drawCrop()});
document.addEventListener('input',e=>{const row=e.target.closest('[data-link-row]');if(!row)return;const preview=row.querySelector('[data-link-preview]');if(preview)preview.outerHTML=BetlemskaTeacherLinks.preview({url:row.querySelector('[name="url"]').value,label:row.querySelector('[name="label"]').value})});
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue=''}});
(async()=>{try{const result=await api();if(result.authenticated)await initSession(result);else showLogin()}catch(e){showLogin(e.message||'Administraci nelze načíst. Obnov stránku.')}})();
})();
